<script setup>import {ref,onMounted} from 'vue';import {api} from '../core';import PetCard from '../components/PetCard.vue';import State from '../components/State.vue';import Icon from '../components/Icon.vue';const keyword=ref(''),category=ref(''),region=ref(''),breed=ref(''),page=ref(1),total=ref(0),items=ref([]),loading=ref(false),error=ref('');async function load(reset=false){if(reset)page.value=1;loading.value=true;error.value='';try{const q=new URLSearchParams({keyword:keyword.value,category:category.value,region:region.value,breed:breed.value,page:page.value});const r=await api('/pets?'+q);items.value=r.items;total.value=r.total}catch(e){error.value=e.message}finally{loading.value=false}}onMounted(()=>load());</script><template><div class="page-intro"><div class="shell"><p class="eyebrow">FIND YOUR FOREVER FRIEND</p><h1>总有一个小生命，与你双向奔赴。</h1><p>认真了解，再做决定。陪伴，是一份长久的承诺。</p></div></div><section class="shell section"><form class="filter-bar" @submit.prevent="load(true)"><label class="search-field"><Icon name="search"/><input v-model="keyword" placeholder="搜索伙伴的名字" aria-label="宠物名称"></label><select v-model="category" aria-label="宠物类别"><option value="">全部伙伴</option><option value="cat">猫咪</option><option value="dog">狗狗</option></select><input v-model="region" placeholder="省份 / 城市" aria-label="地区"><input v-model="breed" placeholder="品种" aria-label="品种"><button class="btn">寻找伙伴</button></form><div class="section-heading compact"><p>共 {{total}} 位伙伴等待新家</p><RouterLink to="/pets/new" class="quiet-link"><Icon name="plus" :size="17"/>发布领养</RouterLink></div><State :loading="loading" :error="error" :empty="!items.length" text="没有找到匹配的伙伴，试试其他条件" @retry="load()"/><div class="pet-grid" v-if="!loading&&!error"><PetCard v-for="p in items" :key="p.id" :pet="p"/></div><div class="pagination"><button class="btn secondary small" :disabled="page===1||loading" @click="page--;load()">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(total/12))}}</span><button class="btn secondary small" :disabled="page*12>=total||loading" @click="page++;load()">下一页</button></div></section></template>
